export function evaluate({ inputs, time, seed, state }) {
  const launchSpeed = inputs.launchSpeed;
  const gravity = inputs.gravity;
  const apexTime = launchSpeed / gravity;
  const apexHeight = launchSpeed * launchSpeed / (2 * gravity);
  const t = time + apexTime; // time since launch
  // Tossed ball
  const tossedY = Math.max(0, launchSpeed * t - 0.5 * gravity * t * t);
  const tossedV = launchSpeed - gravity * t;
  const tossedA = -gravity;
  // Drop ball
  const dropHeld = t < apexTime;
  const dropY = dropHeld ? apexHeight : Math.max(0, launchSpeed * t - 0.5 * gravity * t * t);
  const dropV = dropHeld ? 0 : -gravity * (t - apexTime);
  const dropA = dropHeld ? 0 : -gravity;
  // Layout constants
  const laneWidth = 200;
  const laneHeight = 300;
  const laneX = 50;
  const laneY = 50;
  const scaleY = laneHeight / 2.2; // pixels per metre
  const tossX = laneX + laneWidth / 4;
  const dropX = laneX + (3 * laneWidth) / 4;
  const ballDiameter = 24;
  // Helper to format numbers
  const fmt = (v) => sdk.format(v, 2);
  // Build objects
  const objects = [];
  // Lanes
  objects.push(...sdk.panel({ x: laneX, y: laneY, w: laneWidth, h: laneHeight, title: "Toss", state: "", id: "lane.toss" }));
  objects.push(...sdk.panel({ x: laneX + laneWidth + 20, y: laneY, w: laneWidth, h: laneHeight, title: "Drop", state: "", id: "lane.drop" }));
  // Axes for each lane (y axis only)
  objects.push(sdk.axis("axis.toss", { x: laneX, y: laneY + laneHeight, length: laneHeight, orientation: "y", min: 0, max: 2.2, ticks: [0, 0.5, 1, 1.5, 2, 2.2], label: "Height (m)", unit: "m" }));
  objects.push(sdk.axis("axis.drop", { x: laneX + laneWidth + 20, y: laneY + laneHeight, length: laneHeight, orientation: "y", min: 0, max: 2.2, ticks: [0, 0.5, 1, 1.5, 2, 2.2], label: "Height (m)", unit: "m" }));
  // Balls
  objects.push(sdk.circle("ball.toss", tossX, laneY + laneHeight - tossedY * scaleY, ballDiameter));
  objects.push(sdk.circle("ball.drop", dropX, laneY + laneHeight - dropY * scaleY, ballDiameter));
  // Vectors
  objects.push(sdk.vector("vec.v.toss", { x: tossX, y: laneY + laneHeight - tossedY * scaleY }, { value: tossedV, direction: "up" }, { label: fmt(tossedV) + " m/s", scale: 20 }));
  objects.push(sdk.vector("vec.v.drop", { x: dropX, y: laneY + laneHeight - dropY * scaleY }, { value: dropV, direction: "up" }, { label: fmt(dropV) + " m/s", scale: 20 }));
  objects.push(sdk.vector("vec.a.toss", { x: tossX, y: laneY + laneHeight - tossedY * scaleY }, { value: tossedA, direction: "up" }, { label: fmt(tossedA) + " m/s²", scale: 15, dash: true }));
  objects.push(sdk.vector("vec.a.drop", { x: dropX, y: laneY + laneHeight - dropY * scaleY }, { value: dropA, direction: "up" }, { label: fmt(dropA) + " m/s²", scale: 15, dash: true }));
  // Gate
  objects.push(sdk.gate("gate", dropX, laneY + laneHeight - apexHeight * scaleY, { open: !dropHeld, w: 30, label: "" }));
  // Callouts
  objects.push(...sdk.callout({ x: tossX + 30, y: laneY + laneHeight - tossedY * scaleY }, [fmt(tossedV) + " m/s", fmt(tossedA) + " m/s²"], { id: "callout.toss" }));
  objects.push(...sdk.callout({ x: dropX + 30, y: laneY + laneHeight - dropY * scaleY }, [fmt(dropV) + " m/s", fmt(dropA) + " m/s²"], { id: "callout.drop" }));
  const frame = sdk.frame(objects, { width: 640, height: 420 });
  const quantities = {
    launchSpeed,
    gravity,
    apexTime,
    apexHeight,
    tossedVelocity: tossedV,
    tossedAcceleration: tossedA,
    tossedHeight: tossedY,
    dropVelocity: dropV,
    dropAcceleration: dropA,
    dropHeight: dropY
  };
  const readouts = [
    { id: "tossedVelocity", value: tossedV },
    { id: "tossedAcceleration", value: tossedA },
    { id: "dropVelocity", value: dropV },
    { id: "dropAcceleration", value: dropA }
  ];
  return { frame, quantities, readouts };
}
